/**
 * Converts the food library into a SQL migration for the `foods` table.
 * Per docs/build-brief.md section 5.
 *
 * Run with: npx tsx scripts/seed-foods.ts
 * Writes: supabase/migrations/<timestamp>_seed_foods_batch_1.sql
 *
 * Diet tiers (strictest to least strict): vegan < vegetarian < eggetarian
 * < pescatarian < non_vegetarian. Each dish is tagged with the loosest
 * tier still required to eat it. No beef anywhere in this library --
 * where the original prototype recipe used beef, it's substituted here
 * (see "Chicken burger", ex-"Cheeseburger"; "Spaghetti bolognese" now
 * specifies chicken or mutton mince rather than unspecified "minced meat").
 *
 * meal_category: which meal(s) this dish suits -- detox, breakfast,
 * lunch, snack, dinner, salad. A dish can suit more than one.
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";

type Diet = "vegan" | "vegetarian" | "eggetarian" | "pescatarian" | "non_vegetarian";
type Meal = "detox" | "breakfast" | "lunch" | "snack" | "dinner" | "salad";

interface Dish {
  name: string;
  cuisine: string;
  diet: Diet;
  meals: Meal[];
  serving: string;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
  ingredients: string;
  method: string;
}

