function sqlString(value: string): string {
  return "'" + value.replace(/'/g, "''") + "'";
}

function sqlArray(values: string[]): string {
  return "array[" + values.map(sqlString).join(", ") + "]::text[]";
}

function toRow(d: Dish): string {
  return `(${sqlString(d.name)}, ${sqlString(d.cuisine)}, ${sqlString(d.diet)}, ${sqlArray(d.meals)}, ${sqlString(d.serving)}, ${d.kcal}, ${d.protein}, ${d.carbs}, ${d.fat}, ${sqlString(d.ingredients)}, ${sqlString(d.method)})`;
}

const sql = `-- Seed data for the global \`foods\` library, batch 1: the original
-- prototype dishes (docs/build-brief.md section 5), reclassified with a
-- diet tier and meal category. Generated by scripts/seed-foods.ts --
-- do not hand-edit; change the script and regenerate instead.

insert into public.foods (name, cuisine, diet, meal_category, serving, kcal, protein_g, carbs_g, fat_g, ingredients, method)
values
${BATCH_1.map(toRow).join(",\n")};
`;

const outPath = join(process.cwd(), "supabase", "migrations", "20260922050000_seed_foods_batch_1.sql");
writeFileSync(outPath, sql, "utf8");
console.log(`Wrote ${BATCH_1.length} dishes to ${outPath}`);

